package org.brightstats.data;
import java.util.*;
import com.google.gson.*;
import org.brightstats.stats.Matrices;
import org.brightstats.data.DataPreparation.*;

/** Append-only fixed row functions, applied to original cells before missing-value preparation. */
public final class DataTransforms {
    private DataTransforms(){}
    public enum Operation {DUMMY,RECODE,AFFINE,LOG,SQRT,SQUARE,PRODUCT,SUM,MEAN,REVERSE}
    public record Specification(Operation operation,List<String> sources,List<String> outputs,List<String> levels,String reference,
                                Map<String,Double> mapping,Double factor,Double offset,Double lower,Double upper,String missingCategory){
        public Specification{Objects.requireNonNull(operation);sources=names(sources);outputs=names(outputs);levels=levels==null?List.of():levels.stream().map(String::strip).toList();reference=reference==null?"":reference.strip();mapping=mapping==null?Map.of():Collections.unmodifiableMap(new LinkedHashMap<>(mapping));if(sources.isEmpty()||sources.size()>64||outputs.isEmpty()||outputs.size()>64||new HashSet<>(outputs).size()!=outputs.size())throw new IllegalArgumentException("Choose 1–64 sources and unique new output names.");if(operation==Operation.DUMMY){if(sources.size()!=1||levels.size()<2||levels.size()>64||new HashSet<>(levels).size()!=levels.size()||levels.stream().anyMatch(String::isBlank)||!reference.isEmpty()&&!levels.contains(reference)||outputs.size()!=levels.size()-(reference.isEmpty()?0:1))throw new IllegalArgumentException("Dummy coding needs one source, 2–64 distinct levels and one output per non-reference level.");}else if(outputs.size()!=1||!levels.isEmpty()||!reference.isEmpty())throw new IllegalArgumentException("Numeric/recode operations create one output and do not use dummy levels/reference.");if(!List.of(Operation.SUM,Operation.MEAN,Operation.PRODUCT).contains(operation)&&sources.size()!=1||operation==Operation.PRODUCT&&(sources.size()<2||sources.size()>3))throw new IllegalArgumentException("Choose one source, or the declared multi-source row operation.");if(operation==Operation.RECODE){if(mapping.isEmpty()||mapping.size()>1000||mapping.keySet().stream().anyMatch(key->key==null||key.isBlank()||!key.equals(key.strip()))||mapping.values().stream().anyMatch(value->value==null||!Double.isFinite(value)))throw new IllegalArgumentException("Recoding needs explicit trimmed source labels and finite numeric targets.");}else if(!mapping.isEmpty())throw new IllegalArgumentException("Mapping entries are only used by RECODE.");for(Double value:Arrays.asList(factor,offset,lower,upper))if(value!=null&&!Double.isFinite(value))throw new IllegalArgumentException("Transform constants must be finite.");if(operation!=Operation.AFFINE&&(factor!=null||offset!=null)||operation!=Operation.REVERSE&&(lower!=null||upper!=null))throw new IllegalArgumentException("Only supply constants used by the selected operation.");if(operation==Operation.REVERSE&&(lower==null||upper==null||!(upper>lower)||!Double.isFinite(upper-lower)))throw new IllegalArgumentException("Reverse coding needs finite ordered declared bounds.");if(missingCategory!=null){missingCategory=missingCategory.strip();if(missingCategory.isEmpty()||operation!=Operation.DUMMY&&operation!=Operation.RECODE||operation==Operation.DUMMY&&!levels.contains(missingCategory)||operation==Operation.RECODE&&!mapping.containsKey(missingCategory))throw new IllegalArgumentException("An explicit missing category must belong to the dummy/recode schema.");}}
    }
    public record Result(Raw raw,Settings settings,List<Column> definitions,Prepared prepared,JsonObject history,List<String> warnings){public Result{definitions=List.copyOf(definitions);history=history.deepCopy();warnings=List.copyOf(warnings);}@Override public JsonObject history(){return history.deepCopy();}}
    private static List<String> names(List<String> values){Objects.requireNonNull(values);return values.stream().map(value->{if(value==null||value.isBlank()||value.strip().length()>160)throw new IllegalArgumentException("Use nonempty transform names of at most 160 characters.");return value.strip();}).toList();}
    public static Result append(JsonObject history,List<String> currentNames,double[][] current,Specification specification){int width=Matrices.width(current,1);if(width!=currentNames.size())throw new IllegalArgumentException("Current numeric names and data differ.");Raw raw;Settings settings;List<Column> definitions;String sourceName;
        if(history==null){List<List<String>> rows=new ArrayList<>();for(var row:current){List<String> cells=new ArrayList<>();for(double value:row)cells.add(Double.toString(value));rows.add(cells);}raw=new Raw(currentNames,rows);settings=new Settings(',',Decimal.DOT,"",Missing.REQUIRE_COMPLETE);definitions=currentNames.stream().map(name->new Column(name,Kind.NUMERIC)).toList();sourceName="Numeric project before fixed row transformations";}
        else{var previous=ImportHistory.read(history);raw=previous.raw();settings=previous.settings();definitions=previous.definitions();sourceName=previous.sourceName();}
        var before=DataPreparation.prepare(raw,settings,definitions);if(!before.columns().equals(currentNames)||!Arrays.deepEquals(before.values(),current))throw new IllegalArgumentException("Current data does not reproduce its original preparation history.");int added=specification.outputs.size();if(raw.headers().size()+added>10000||(long)raw.rows().size()*(raw.headers().size()+added)>5000000L)throw new IllegalArgumentException("Transformed source exceeds five million cells.");Set<String> existing=new HashSet<>();for(var column:definitions)existing.add(column.name());for(String output:specification.outputs)if(!existing.add(output))throw new IllegalArgumentException("New transform name already exists: "+output);int[] sources=new int[specification.sources.size()];for(int i=0;i<sources.length;i++){String name=specification.sources.get(i);sources[i]=-1;for(int j=0;j<definitions.size();j++)if(definitions.get(j).name().equals(name))sources[i]=j;if(sources[i]<0)throw new IllegalArgumentException("Transform source is missing: "+name);}
        List<List<String>> rows=new ArrayList<>();for(int row=0;row<raw.rows().size();row++){if((row&255)==0)Matrices.interrupted();var original=raw.rows().get(row);List<String> values=new ArrayList<>(original);try{values.addAll(evaluate(original,sources,settings,specification));}catch(IllegalArgumentException problem){throw new IllegalArgumentException("Source row "+(row+1)+": "+problem.getMessage(),problem);}rows.add(values);}
        List<String> headers=new ArrayList<>(raw.headers());headers.addAll(specification.outputs);List<Column> extended=new ArrayList<>(definitions);for(String output:specification.outputs)extended.add(new Column(output,Kind.NUMERIC));Raw transformed=new Raw(headers,rows);var prepared=DataPreparation.prepare(transformed,settings,extended);if(!prepared.sourceRows().equals(before.sourceRows()))throw new IllegalArgumentException("This transform would change the retained source rows. Revise its missing/unknown-category policy or prepare it as a new import.");double[][] actual=prepared.values();for(int row=0;row<current.length;row++)for(int column=0;column<width;column++)if(Double.doubleToLongBits(actual[row][column])!=Double.doubleToLongBits(current[row][column]))throw new IllegalArgumentException("Transform unexpectedly changed an existing numeric cell.");
        JsonObject captured=ImportHistory.capture(sourceName,transformed,settings,extended);if(history!=null)for(var entry:history.entrySet())if(!captured.has(entry.getKey())&&!entry.getKey().equals("transformations"))captured.add(entry.getKey(),entry.getValue().deepCopy());JsonArray lineage=history!=null&&history.has("transformations")?history.getAsJsonArray("transformations").deepCopy():new JsonArray();JsonObject step=new JsonObject();step.add("specification",new GsonBuilder().serializeNulls().create().toJsonTree(specification));step.addProperty("inputRawColumns",raw.headers().size());step.addProperty("outputRawColumns",headers.size());step.addProperty("trainingDependentEstimates",false);lineage.add(step);captured.add("transformations",lineage);List<String>warnings=new ArrayList<>(prepared.warnings());warnings.add("New features are fixed row functions of original source cells before missing-value preparation. Missing derived cells are prepared under the declared policy; prediction can recover them before fold-local imputation.");if(specification.operation==Operation.DUMMY&&specification.missingCategory==null&&prepared.replacedCells()>before.replacedCells())warnings.add("Mean replacement of missing dummy cells can create fractional codes; use an explicit missing category or complete cases when genuine 0/1 values are required.");warnings.add("Dummy/recode category matching uses trimmed source text exactly. Declare numeric code spelling explicitly or normalize it with a recode; unknown categories are rejected.");if(specification.operation==Operation.DUMMY&&specification.reference.isEmpty())warnings.add("All-category dummy columns sum to one. Omit a reference level when using a regression intercept to avoid perfect collinearity.");return new Result(transformed,settings,extended,prepared,captured,warnings);
    }
    private static List<String> evaluate(List<String> row,int[] sources,Settings settings,Specification spec){List<String> output=new ArrayList<>();if(spec.operation==Operation.DUMMY||spec.operation==Operation.RECODE){String original=row.get(sources[0]),value=original.strip();boolean missing=DataPreparation.missing(original,settings);if(missing){if(spec.missingCategory==null)return Collections.nCopies(spec.outputs.size(),"");value=spec.missingCategory;}else if(value.equals(spec.missingCategory))throw new IllegalArgumentException("Observed category collides with the explicit missing-category label.");if(spec.operation==Operation.RECODE){Double code=spec.mapping.get(value);if(code==null)throw new IllegalArgumentException("Unmapped recode category; revise the declared mapping.");return List.of(text(code,settings));}if(!spec.levels.contains(value))throw new IllegalArgumentException("Unknown dummy category; revise the declared levels.");for(String level:spec.levels)if(!level.equals(spec.reference))output.add(value.equals(level)?"1":"0");return output;}
        double[] values=new double[sources.length];for(int i=0;i<sources.length;i++){String cell=row.get(sources[i]);if(DataPreparation.missing(cell,settings))return List.of("");values[i]=DataPreparation.number(cell,settings.decimal());}double value=switch(spec.operation){case AFFINE->Math.fma(spec.factor==null?1:spec.factor,values[0],spec.offset==null?0:spec.offset);case LOG->{if(!(values[0]>0))throw new IllegalArgumentException("LOG requires positive original values.");yield StrictMath.log(values[0]);}case SQRT->{if(values[0]<0)throw new IllegalArgumentException("SQRT requires nonnegative original values.");yield StrictMath.sqrt(values[0]);}case SQUARE->values[0]*values[0];case PRODUCT->{double product=1;for(double x:values)product*=x;yield product;}case SUM->{double sum=0;for(double x:values)sum+=x;yield sum;}case MEAN->{double mean=0;for(int i=0;i<values.length;i++)mean+=(values[i]-mean)/(i+1);yield mean;}case REVERSE->{if(values[0]<spec.lower||values[0]>spec.upper)throw new IllegalArgumentException("Reverse-coded value lies outside its declared bounds.");yield spec.lower+(spec.upper-values[0]);}default->throw new IllegalArgumentException("Unsupported fixed numeric transform.");};if(!Double.isFinite(value))throw new IllegalArgumentException("Transformed value exceeds the finite numeric range.");return List.of(text(value,settings));}
    public static void verifyLineage(JsonObject document,ImportHistory.History history){var lineage=document.getAsJsonArray("transformations");if(lineage.size()>1000)throw new IllegalArgumentException("Too many fixed transform steps.");int previous=-1;for(var element:lineage){var step=element.getAsJsonObject();int input=step.get("inputRawColumns").getAsBigDecimal().intValueExact(),output=step.get("outputRawColumns").getAsBigDecimal().intValueExact();var spec=new Gson().fromJson(step.get("specification"),Specification.class);if(input<1||output!=input+spec.outputs.size()||output>history.raw().headers().size()||previous>=0&&input!=previous||!step.has("trainingDependentEstimates")||!step.get("trainingDependentEstimates").isJsonPrimitive()||!step.get("trainingDependentEstimates").getAsJsonPrimitive().isBoolean()||step.get("trainingDependentEstimates").getAsBoolean())throw new IllegalArgumentException("Invalid fixed-transform lineage dimensions or fitting claim.");for(int i=0;i<spec.outputs.size();i++)if(!history.raw().headers().get(input+i).equals(spec.outputs.get(i))||!history.definitions().get(input+i).name().equals(spec.outputs.get(i)))throw new IllegalArgumentException("Derived output identity differs from its lineage.");int[] sources=new int[spec.sources.size()];for(int i=0;i<sources.length;i++){sources[i]=-1;for(int j=0;j<input;j++)if(history.definitions().get(j).name().equals(spec.sources.get(i)))sources[i]=j;if(sources[i]<0)throw new IllegalArgumentException("Transform lineage references a missing/later source.");}for(int row=0;row<history.raw().rows().size();row++){if((row&255)==0)Matrices.interrupted();var cells=history.raw().rows().get(row);var expected=evaluate(cells,sources,history.settings(),spec);for(int column=0;column<expected.size();column++)if(!expected.get(column).equals(cells.get(input+column)))throw new IllegalArgumentException("Derived source cell does not match its fixed transformation at source row "+(row+1)+".");}previous=output;}if(previous>=0&&previous!=history.raw().headers().size())throw new IllegalArgumentException("Unaccounted columns follow the recorded transformation lineage.");}
    private static String text(double value,Settings settings){String text=Double.toString(value);return settings.decimal()==Decimal.COMMA?text.replace('.',','):text;}
}
